#!/bin/sh
# Name: Brew Reader
# Author: Alex Kisch
# Icon: data:image/png;base64,
# DontUseFBInk

# Launcher pattern from KWordle / KindleForge: copy the app into mesquite, register it, start it.

SOURCE_DIR="/mnt/us/documents/brewreader"
TARGET_DIR="/var/local/mesquite/brewreader"
DB="/var/local/appreg.db"
APP_ID="com.alexkisch.brewreader"

if [ -d "$SOURCE_DIR" ]; then
    [ -d "$TARGET_DIR" ] && rm -rf "$TARGET_DIR"
    cp -r "$SOURCE_DIR" "$TARGET_DIR"
else
    exit 1
fi

sqlite3 "$DB" <<EOF
INSERT OR IGNORE INTO interfaces(interface) VALUES('application');
INSERT OR IGNORE INTO handlerIds(handlerId) VALUES('$APP_ID');
INSERT OR REPLACE INTO properties(handlerId,name,value) VALUES('$APP_ID','lipcId','$APP_ID');
INSERT OR REPLACE INTO properties(handlerId,name,value) VALUES('$APP_ID','command','/usr/bin/mesquite -l $APP_ID -c file://$TARGET_DIR/');
INSERT OR REPLACE INTO properties(handlerId,name,value) VALUES('$APP_ID','supportedOrientation','U');
EOF

# Local copy of today's issue, used by the app if its own request is blocked. Downloaded in the
# background so it doesn't delay startup; written to a temp file so the app never reads a partial page.
# Empty placeholder so the app never requests a missing file (the app retries until it has content).
: > "$TARGET_DIR/latest.html"
nohup sh -c "curl -fsSL -m 20 -A 'Mozilla/5.0' -o '$TARGET_DIR/latest.tmp' https://www.morningbrew.com/issues/latest && mv '$TARGET_DIR/latest.tmp' '$TARGET_DIR/latest.html'" >/dev/null 2>&1 &

echo Registered $APP_ID, You May Now Launch It With LIPC.
# Kept from the KWordle/KindleForge launchers; removing it coincided with the app crashing on launch.
sleep 2

nohup lipc-set-prop com.lab126.appmgrd start app://$APP_ID >/dev/null 2>&1 &
